/// The palette index at (x, y), 0 = clear
inline uint8_t at(int16_t x, int16_t y) {
    if (x < 0 || y < 0 || x >= W || y >= H) return 0;
    const uint8_t b = PIXELS[y][x >> 1];
    return (x & 1) ? static_cast<uint8_t>(b & 0x0F) : static_cast<uint8_t>(b >> 4);
}

